#include <iostream>
#include <algorithm>
using namespace std;

// Function to remove duplicates from array
int removeDuplicates(int arr[], int n) {
    if (n <= 1) return n;

    // Sort array first to bring duplicates together
    sort(arr, arr + n);

    int j = 0;
    for (int i = 0; i < n - 1; i++) {
        if (arr[i] != arr[i + 1]) {
            arr[j++] = arr[i];
        }
    }
    arr[j++] = arr[n - 1];

    return j;
}

// Recursive merge
